import Foundation
import XCTest
@testable import GunnAire_Ops

/// Generated from the real backend HTTP packaging/key routes using only isolated
/// synthetic test identities. This fixture key is public test data, not a secret.
final class StaffReplicaServerInteropTests: XCTestCase {
    struct Vector: Decodable {
        let workspace: CompanyWorkspaceIdentity
        let plan: CloudKitStaffSharePlan
        let owner: StaffReplicaProjectionReceipt
        let staff: StaffReplicaProjectionReceipt
    }
    @MainActor func testRealBackendSealedPayloadOpensWithNativeCryptoKitAndExactScope() throws {
        let vector = try JSONDecoder().decode(Vector.self, from: Data(Self.fixture.utf8))
        let now = try XCTUnwrap(SharedTimeError.date(vector.owner.manifest.createdAt))
        try vector.owner.validate(plan: vector.plan, workspace: vector.workspace, now: now)
        try vector.staff.validate(plan: vector.plan, workspace: vector.workspace, now: now)
        let original = try vector.owner.ownerSealedPayload()
        XCTAssertEqual(try vector.staff.decryptionKey(), original.key)
        XCTAssertNil(vector.staff.sealedBase64)
        XCTAssertEqual(original.manifest.recordCount, 8)
        XCTAssertEqual(original.bytes.count, original.manifest.payloadBytes + 28)
        XCTAssertEqual(StaffReplicaManifest.hash(original.opened.bytes), original.manifest.payloadSHA256)
        let graph = try StaffReplicaCoreGraph(payload: original.opened, plan: vector.plan, workspace: vector.workspace, now: now)
        XCTAssertEqual(graph.records.count, 8)
        let attachment = XCTAttachment(data: original.opened.bytes, uniformTypeIdentifier: "public.json")
        attachment.name = "Real backend staff payload opened by native CryptoKit"
        attachment.lifetime = .keepAlways
        add(attachment)
    }
